#!/bin/bash # Reproduce "EOF: command not found" by editing a script in place while it runs. SRC=/Users/nick.davis/gitrepos/opg-use-an-lpa/test_unused_accounts.sh
run_case() { local label="$1" file="$2" # Make the 'logs' command slow and harmless sed 's/^ make logs unused-accounts-lambda$/ sleep 2/' "$file" > /tmp/t.sh bash /tmp/t.sh logs > /tmp/t.out 2>&1 & local pid=$! sleep 1 # Rewrite in place (same inode) with 10 extra lines at the top, like an editor save { head -1 /tmp/t.sh; for i in $(seq 1 10); do echo "# padding $i"; done; tail -n +2 /tmp/t.sh; } > /tmp/t.new cat /tmp/t.new > /tmp/t.sh wait $pid echo "[$label] exit=$?" grep -i "command not found\|syntax error" /tmp/t.out || echo "[$label] no stray errors" }
# Old layout (no { ...; exit; } wrapper) for comparison sed -e '/^# Wrapped in {/d' -e '/^# This makes it safe/d' -e '/^{$/d' -e '/^exit$/d' -e '$d' "$SRC" > /tmp/old_layout.sh bash -n /tmp/old_layout.sh || { echo "old layout build failed"; exit 1; } run_case "old" /tmp/old_layout.sh run_case "new" "$SRC" rm -f /tmp/t.sh /tmp/t.new /tmp/t.out /tmp/old_layout.sh
